package com.college.erp.model.entity;
import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document; import java.time.Instant;
@Document("notifications") public class NotificationDocument { @Id String id; String username,title,message,type; boolean read; Instant createdAt=Instant.now(); public String getId(){return id;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getMessage(){return message;} public void setMessage(String v){message=v;} public String getType(){return type;} public void setType(String v){type=v;} public boolean isRead(){return read;} public void setRead(boolean v){read=v;} public Instant getCreatedAt(){return createdAt;} }
